import { communications, communicationClasses, communicationStudents, communicationChildren, consentFor } from "./communications-data.js";
import { feeToday } from "./fees-data.js";
import { badge, button, escapeHtml as e, pageHeading, emptyState } from "./ui.js";
const err = '<p class="form-error" hidden role="alert"></p>';
export function communicationsPage(options) { return page(options, "message"); }
export function eventsPage(options) { return page(options, "event"); }
function page({ state, context }, kind) {
  const parent = context.role === "parent", events = kind === "event", items = communications(state, context, kind);
  return `${pageHeading(events ? "Events & consent" : "Letters & email", parent ? "Updates for all your linked children" : "Your teaching classes · Whole class or selected students", parent ? "" : button(events ? "Create event / trip" : "Compose communication", "portal-compose", { value: kind }))}
    <div class="portal-feed">${items.map((item) => {
      const students = communicationChildren(state, context, item), responses = students.map((student) => consentFor(state, item.id, student.id)), open = item.status === "published" && item.deadline >= feeToday();
      return `<article class="surface portal-card"><div class="portal-row">${badge(item.status === "cancelled" ? "Cancelled" : events ? "Consent request" : item.channel === "email" ? "Email · demo" : "Letter", item.status === "cancelled" ? "neutral" : "blue")}${badge("Class " + e(item.className), "neutral")}</div><h2>${e(item.title)}</h2><p class="portal-muted">From ${e(item.by)}${events ? ` · ${e(item.eventDate)} · ${e(item.location)}` : ""}</p><p class="portal-message">${e(item.message)}</p>${events ? `<p>Consent deadline: <strong>${e(item.deadline)}</strong>${!open ? " · Responses closed" : ""}</p>` : ""}
      ${parent ? students.map((student) => { const response = consentFor(state, item.id, student.id); return `<div class="consent-student"><div><strong>${e(student.name)}</strong><p>${e(student.admissionNumber)}${events ? " · " + (response ? (response.decision === "yes" ? "Consent given" : "Not attending") + " · " + e(response.by) : "Awaiting your response") : ""}</p></div>${events && open ? button(response ? "Change response" : "Respond", "portal-consent", { value: item.id + "|" + student.id }) : ""}</div>`; }).join("") : `<div class="portal-stats compact"><span>${students.length} students</span><span>${students.filter((student) => !item.recipients.some((recipient) => recipient.studentId === student.id)).length} without guardian delivery</span>${events ? `<span>${responses.filter((response) => response?.decision === "yes").length} yes · ${responses.filter((response) => response?.decision === "no").length} no · ${responses.filter((response) => !response).length} pending</span>` : ""}</div><details class="portal-recipient-details"><summary>Recipient & response register</summary>${students.map((student) => `<div class="portal-list-link"><div><strong>${e(student.name)}</strong><small>${e(student.admissionNumber)} · ${item.recipients.filter((recipient) => recipient.studentId === student.id).map((recipient) => e(state.accounts.find((person) => person.id === recipient.parentId)?.name)).join(", ") || "No linked guardian — school follow-up required"}</small></div>${events ? badge(e(consentFor(state, item.id, student.id)?.decision || "pending"), "neutral") : ""}</div>`).join("")}</details>`}
      <div class="portal-actions">${button("Download letter", "portal-letter", { value: item.id, variant: "secondary" })}${!parent && events ? button("Export consent register", "portal-event-export", { value: item.id, variant: "secondary" }) : ""}${!parent && open && events ? button("Remind pending parents", "portal-event-remind", { value: item.id, variant: "secondary" }) : ""}${!parent && item.status === "published" ? button(events ? "Cancel event" : "Withdraw communication", "portal-cancel-communication", { value: item.id, variant: "secondary" }) : ""}</div></article>`;
    }).join("") || `<section class="surface">${emptyState("file", events ? "No events yet" : "No communications yet", parent ? "Messages for your linked children will appear here." : "Choose a teaching class to get started.")}</section>`}</div>`;
}
export function composeForm(state, context, kind, draft = {}) {
  const classes = communicationClasses(state, context), selected = classes.find((item) => item.id === draft.classId) || classes[0];
  if (!selected) return emptyState("users", "No assigned classes", "A current class appointment or subject assignment is required.");
  const students = communicationStudents(state, context, selected.id);
  return `<form class="portal-form" data-form="portal-compose"><input type="hidden" name="kind" value="${kind}"><label>Teaching class<select name="classId" data-change="portal-compose-class">${classes.map((item) => `<option value="${e(item.id)}" ${selected.id === item.id ? "selected" : ""}>${e(item.title)}</option>`).join("")}</select></label><div class="portal-form-grid"><label>Format<select name="channel"><option value="letter" ${draft.channel === "letter" ? "selected" : ""}>Letter</option><option value="email" ${draft.channel === "email" ? "selected" : ""}>Email · demo</option></select></label><label>Recipients<select name="audience" data-change="portal-compose-audience"><option value="whole" ${draft.audience !== "selected" ? "selected" : ""}>Whole class</option><option value="selected" ${draft.audience === "selected" ? "selected" : ""}>Selected students</option></select></label></div><fieldset class="recipient-list" ${draft.audience !== "selected" ? "hidden" : ""}><legend>Select students</legend>${students.map((student) => `<label class="portal-check"><input type="checkbox" name="students" value="${e(student.id)}" ${draft.students?.includes(student.id) ? "checked" : ""}>${e(student.name)} · ${e(student.admissionNumber)}</label>`).join("")}</fieldset><label>Title<input name="title" value="${e(draft.title || "")}" maxlength="120" required></label><label>Message / letter<textarea name="message" required maxlength="4000" rows="5">${e(draft.message || "")}</textarea></label>${kind === "event" ? `<div class="portal-form-grid"><label>Event date<input type="date" name="eventDate" value="${e(draft.eventDate || "")}" required></label><label>Consent deadline<input type="date" name="deadline" value="${e(draft.deadline || "")}" min="${feeToday()}" required></label></div><label>Location<input name="location" value="${e(draft.location || "")}" maxlength="160" required></label>` : ""}<p>Parents receive an in-portal copy. Email delivery and printed-letter distribution are demonstration steps.</p>${err}<button class="button primary">Preview recipients & message</button></form>`;
}
export function communicationPreview(state, item, input) {
  const hidden = Object.entries(input).filter(([key]) => key !== "students").map(([key, value]) => `<input type="hidden" name="${e(key)}" value="${e(value)}">`).join("") + input.students.map((id) => `<input type="hidden" name="students" value="${e(id)}">`).join("");
  return `<form data-form="portal-publish" class="portal-form">${hidden}<h3>${e(item.title)}</h3><p class="portal-message">${e(item.message)}</p><h3>Recipient preview</h3><p>${item.studentIds.length} students · ${item.recipients.length} guardian portal copies</p>${item.studentIds.map((id) => { const student = state.students.find((student) => student.id === id), recipients = item.recipients.filter((recipient) => recipient.studentId === id); return `<p><strong>${e(student.name)}</strong><br>${recipients.map((recipient) => e(state.accounts.find((person) => person.id === recipient.parentId)?.name)).join(", ") || "No linked guardian — no portal delivery"}</p>`; }).join("")}${err}<button class="button primary">${item.kind === "event" ? "Publish consent request" : "Share with parents"}</button></form>`;
}
export function consentForm(state, context, id, studentId) {
  const event = communications(state, context, "event").find((item) => item.id === id), student = event && communicationChildren(state, context, event).find((item) => item.id === studentId);
  if (!event || !student) throw new Error("Choose an event for your child.");
  const response = consentFor(state, id, studentId);
  return `<form class="portal-form" data-form="portal-consent"><input type="hidden" name="eventId" value="${e(id)}"><input type="hidden" name="studentId" value="${e(studentId)}"><h3>${e(event.title)}</h3><p>${e(student.name)} · ${e(event.eventDate)} · ${e(event.location)}</p><label>Consent response<select name="decision"><option value="yes" ${response?.decision === "yes" ? "selected" : ""}>I give consent for my child to attend</option><option value="no" ${response?.decision === "no" ? "selected" : ""}>My child will not attend</option></select></label><label>Type your guardian name: ${e(context.account.name)}<input name="signature" autocomplete="off" required placeholder="${e(context.account.name)}"></label><p>Demo consent is recorded per child. You may change it until ${e(event.deadline)}.</p>${err}<button class="button primary">Save consent response</button></form>`;
}
export function letterHTML(state, context, id) {
  const item = communications(state, context).find((item) => item.id === id); if (!item) throw new Error("Choose an accessible communication.");
  // Parent copy never includes classmates, guardian lists or class-wide response registers.
  return `<!doctype html><html><meta charset="utf-8"><title>${e(item.title)}</title><style>body{font:18px/1.65 system-ui;max-width:760px;margin:60px auto;padding:24px;color:#193d32}header{border-bottom:3px solid #b6933e}p{white-space:pre-wrap}@media print{button{display:none}}</style><header><h2>School Management Platform</h2><p>DEMO ${item.channel === "email" ? "EMAIL COPY" : "LETTER"} · Class ${e(item.className)}</p></header><h1>${e(item.title)}</h1><p>${e(item.message)}</p>${item.kind === "event" ? `<p>Event: ${e(item.eventDate)} · ${e(item.location)}\nConsent deadline: ${e(item.deadline)}. Respond in the Parent portal.</p>` : ""}<p>${e(item.by)}</p><p>Status: ${e(item.status)}</p><button onclick="window.print()">Print / Save PDF</button></html>`;
}
